import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (value: Date | null) => void;
}

const startOfDay = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (days: number) => {
  const base = startOfDay(new Date());
  base.setDate(base.getDate() + days);
  return base;
};

const presets = [
  { value: 'today', label: 'Сегодня', offset: 0 },
  { value: 'yesterday', label: 'Вчера', offset: -1 },
  { value: 'week', label: 'Неделя назад', offset: -7 },
];

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [date, setDate] = useState<Date | null>(null);

  const apply = (next: Date | null) => {
    setDate(next);
    onChange?.(next);
  };

  const selectedTime = date ? startOfDay(date).getTime() : null;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
        {presets.map((preset) => (
          <JxChip
            key={preset.value}
            active={selectedTime === shiftDays(preset.offset).getTime()}
            onClick={() => apply(shiftDays(preset.offset))}
          >
            {preset.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar locale="ru-RU" value={date} onValueChange={apply} />
    </div>
  );
}

